let input := read_file("project/changes.txt")
let lines := split(input, "\n")
mut bullets := []

for line in lines {
    let cleaned := trim(line)
    if len(cleaned) > 0 {
        bullets = push(bullets, "- " + cleaned)
    }
}

let document := "# Release notes\n\n" + join(bullets, "\n")
write_file("project/RELEASE-NOTES.md", document, true)
print(document)
